/**
 * A estrutura do livro de Revelação — porte de `componentes/viz/revelacao.js`.
 *
 * EM CIMA, o mapa do livro: as 16 visões como faixas com a LARGURA real em
 * versículos (a 1ª ocupa 62; a 3ª, dos quatro cavaleiros, só 17). Dá o "onde
 * estou".
 *
 * EMBAIXO, o ROLO ABERTO — o motivo desta viz existir. A lista de 16 visões não
 * mostra o encaixe: o 7º selo não traz um evento, traz as SETE TROMBETAS; a 7ª
 * trombeta não traz um evento, traz o Reino. O rolo é desenhado aberto entre duas
 * varetas: de um lado os sete selos; ao abrir o 7º, o rolo VIRA na ponta e segue
 * na fita de baixo, as trombetas, terminando no miolo — o Reino. A cor é
 * identidade (selo azul, trombeta roxa, Reino ouro) e quem destaca é o brilho.
 *
 * **Esta é a única viz que não usa os tokens do tema.** Ela desenha um objeto
 * físico — um pergaminho velho entre duas varetas de madeira —, e pergaminho tem
 * a cor que tem; recolori-lo pelo tema faria a metáfora perder o sentido. A cena
 * traz o próprio fundo claro e é legível nos dois temas.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import { type EstadoDaViz, infoDe, limitar, textoDe } from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** Versículos por capítulo do Apocalipse (404 no total). */
const VERSOS = [
  20, 29, 22, 11, 14, 17, 17, 13, 21, 11, 19, 17, 18, 20, 8, 21, 18, 24, 21, 15, 27, 21,
];

/** Soma corrida, para converter "capítulo:versículo" em versículo absoluto. */
const ACUMULADO: number[] = [0];
for (const versos of VERSOS) ACUMULADO.push((ACUMULADO[ACUMULADO.length - 1] ?? 0) + versos);
const TOTAL = ACUMULADO[22] ?? 404;

function absoluto(referencia: readonly number[]): number {
  return (ACUMULADO[(referencia[0] ?? 1) - 1] ?? 0) + (referencia[1] ?? 0);
}

const OURO = '#f0b429';
const OURO_CLARO = '#ffe08a';
const AZUL = '#2f6fb0';
const AZUL_BORDA = '#1c4e86';
const ROXO = '#8659c4';
const ROXO_BORDA = '#5a3597';
const PERGA = '#efe1bd';
const PERGA_SOMBRA = '#c9ab74';
const PERGA_LUZ = '#fff8e6';
const MADEIRA = '#6b4a2a';
const MADEIRA_LUZ = '#9c7040';
const FRACO = '#93805a';
const FUNDO = '#f5eeda';

const TAU = Math.PI * 2;

/**
 * Uma visão como o módulo a entrega: o número dela é `n`, e não `id` — este
 * arquivo lia `id`, e o mapa do livro saía com dezesseis "undefined" escritos
 * por cima das faixas. O estado atravessa a fronteira como `Record<string,
 * unknown>`, então o `tsc` não tinha como acusar.
 */
interface VisaoNoMapa {
  readonly n: number;
  readonly ini: readonly number[];
  readonly fim: readonly number[];
}

const revelacaoViz: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function caminhoArredondado(
    ctx: CanvasRenderingContext2D,
    x: number,
    y: number,
    largura: number,
    altura: number,
    raio: number,
  ): void {
    ctx.beginPath();
    ctx.roundRect(x, y, largura, altura, raio);
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const info = infoDe(estado);
    const visoes = Array.isArray(info.visoes) ? (info.visoes as VisaoNoMapa[]) : [];
    const ativo = Number(info.ativo);
    const vistos = new Set(Array.isArray(info.vistos) ? (info.vistos as number[]) : []);
    const ramo = textoDe(info, 'ramo');

    // ── Registro 1: o mapa do livro ─────────────────────────────────────────
    const margem = L * 0.05;
    const yMapa = A * 0.07;
    const hMapa = A * 0.05;
    const X = (verso: number): number => margem + (L - 2 * margem) * (verso / TOTAL);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.font = `600 ${Math.round(A * 0.026)}px system-ui, sans-serif`;
    ctx.fillStyle = FRACO;
    ctx.fillText('O LIVRO — 16 visões, 404 versículos', margem, yMapa - A * 0.014);

    // Os trechos fora das visões (o prólogo e o epílogo) ficam esmaecidos.
    ctx.fillStyle = PERGA_SOMBRA;
    ctx.globalAlpha = 0.6;
    caminhoArredondado(ctx, X(0), yMapa, Math.max(X(absoluto([1, 10])) - X(0), 1), hMapa, 2);
    ctx.fill();
    caminhoArredondado(
      ctx,
      X(absoluto([22, 5])),
      yMapa,
      Math.max(X(TOTAL) - X(absoluto([22, 5])), 1),
      hMapa,
      2,
    );
    ctx.fill();
    ctx.globalAlpha = 1;

    for (const visao of visoes) {
      const x1 = X(absoluto(visao.ini));
      const x2 = X(absoluto(visao.fim));
      const marcada = visao.n === ativo;
      const visitada = vistos.has(visao.n);

      ctx.fillStyle = marcada ? OURO : visitada ? AZUL : '#d7c39a';
      caminhoArredondado(ctx, x1 + 0.6, yMapa, Math.max(x2 - x1 - 1.6, 1.4), hMapa, 2);
      ctx.fill();

      // O número só cabe nas faixas largas o bastante para lê-lo.
      if (x2 - x1 > A * 0.03) {
        ctx.fillStyle = marcada ? '#3a2f14' : visitada ? '#ffffff' : '#6b5a34';
        ctx.font = `700 ${Math.round(A * 0.022)}px system-ui, sans-serif`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(String(visao.n), (x1 + x2) / 2, yMapa + hMapa / 2);
      }
    }

    // ── Registro 2: o rolo aberto ───────────────────────────────────────────
    const topo = yMapa + hMapa + A * 0.05;
    // Sobra para a legenda.
    const fundo = A - A * 0.085;
    const alturaRolo = fundo - topo;

    const yCima = topo + alturaRolo * 0.3;
    const yBaixo = topo + alturaRolo * 0.74;
    const fita = limitar(alturaRolo * 0.3, 16, 46);

    const xVaretaEsq = L * 0.055;
    const xVaretaDir = L * 0.945;
    const xColuna1 = L * 0.215;
    const xColuna7 = L * 0.845;
    const passo = (xColuna7 - xColuna1) / 6;
    const colunaX = (i: number): number => xColuna1 + passo * i;

    const raioSelo = limitar(passo * 0.34, 9, 17);
    const raioTrombeta = limitar(passo * 0.3, 8, 15);
    const raioReino = limitar(fita * 0.66, 13, 26);
    const xReino = L * 0.115;

    const xVirada = xColuna7;
    const barriga = L * 0.06;
    const yMeio = (yCima + yBaixo) / 2;

    /** Um ponto da curva da virada, para a faísca percorrer. */
    const pontoDaVirada = (s: number): [number, number] => {
      const m = 1 - s;
      return [
        m * m * xVirada + 2 * m * s * (xVirada + barriga) + s * s * xVirada,
        m * m * yCima + 2 * m * s * yMeio + s * s * yBaixo,
      ];
    };

    const tracoDaVirada = (cor: string, largura: number, alfa = 1): void => {
      ctx.beginPath();
      ctx.moveTo(xVirada, yCima);
      ctx.quadraticCurveTo(xVirada + barriga, yMeio, xVirada, yBaixo);
      ctx.lineCap = 'round';
      ctx.lineWidth = largura;
      ctx.strokeStyle = cor;
      ctx.globalAlpha = alfa;
      ctx.stroke();
      ctx.globalAlpha = 1;
    };

    function vareta(cx: number): void {
      const largura = limitar(L * 0.02, 6, 12);
      const yA = topo + alturaRolo * 0.04;
      const yB = fundo + alturaRolo * 0.02;

      caminhoArredondado(ctx, cx - largura / 2, yA, largura, yB - yA, largura / 2);
      ctx.fillStyle = MADEIRA;
      ctx.fill();

      caminhoArredondado(
        ctx,
        cx - largura * 0.14,
        yA + 5,
        largura * 0.28,
        yB - yA - 10,
        largura * 0.14,
      );
      ctx.fillStyle = MADEIRA_LUZ;
      ctx.globalAlpha = 0.6;
      ctx.fill();
      ctx.globalAlpha = 1;

      for (const cy of [yA, yB]) {
        ctx.beginPath();
        ctx.ellipse(cx, cy, largura * 0.9, largura * 0.5, 0, 0, TAU);
        ctx.fillStyle = '#7d5730';
        ctx.fill();
      }
    }

    vareta(xVaretaEsq);
    vareta(xVaretaDir);

    /** Que peças acendem, conforme a visão aberta. */
    const seloAceso = (i: number): boolean =>
      ramo === 'rolo' ||
      (ramo === 'selos16' && i < 6) ||
      (ramo === 'entre67' && i === 5) ||
      (ramo === 'selo7' && i === 6);
    const trombetaAcesa = (i: number): boolean =>
      (ramo === 'selo7' && i < 6) || (ramo === 'tromb7' && i === 6);
    const reinoAceso = ramo === 'tromb7';

    // Pergaminho: fita de cima, a virada e fita de baixo.
    const xInicio = xVaretaEsq + fita * 0.2;
    const larguraFita = xVirada - xInicio;

    ctx.fillStyle = PERGA_SOMBRA;
    ctx.globalAlpha = 0.4;
    caminhoArredondado(
      ctx,
      xInicio - 4,
      yCima - fita / 2 - 4,
      larguraFita + 8,
      fita + 8,
      fita * 0.3,
    );
    ctx.fill();
    caminhoArredondado(
      ctx,
      xInicio - 4,
      yBaixo - fita / 2 - 4,
      larguraFita + 8,
      fita + 8,
      fita * 0.3,
    );
    ctx.fill();
    ctx.globalAlpha = 1;
    tracoDaVirada(PERGA_SOMBRA, fita + 8, 0.4);

    ctx.fillStyle = PERGA;
    caminhoArredondado(ctx, xInicio, yCima - fita / 2, larguraFita, fita, fita * 0.28);
    ctx.fill();
    caminhoArredondado(ctx, xInicio, yBaixo - fita / 2, larguraFita, fita, fita * 0.28);
    ctx.fill();
    tracoDaVirada(PERGA, fita);

    ctx.fillStyle = PERGA_LUZ;
    ctx.globalAlpha = 0.6;
    caminhoArredondado(
      ctx,
      xInicio + 6,
      yCima - fita / 2 + fita * 0.14,
      larguraFita - 12,
      fita * 0.12,
      3,
    );
    ctx.fill();
    caminhoArredondado(
      ctx,
      xInicio + 6,
      yBaixo - fita / 2 + fita * 0.14,
      larguraFita - 12,
      fita * 0.12,
      3,
    );
    ctx.fill();
    ctx.globalAlpha = 1;

    // Tinta de identidade: azul nos selos (cima), roxo nas trombetas (baixo).
    ctx.lineCap = 'round';
    ctx.globalAlpha = 0.85;
    ctx.lineWidth = limitar(fita * 0.12, 3, 6);
    ctx.strokeStyle = AZUL;
    ctx.beginPath();
    ctx.moveTo(colunaX(0), yCima);
    ctx.lineTo(colunaX(6), yCima);
    ctx.stroke();
    ctx.strokeStyle = ROXO;
    ctx.beginPath();
    ctx.moveTo(colunaX(6), yBaixo);
    ctx.lineTo(colunaX(0), yBaixo);
    ctx.stroke();
    ctx.globalAlpha = 1;

    // A virada: a tinta troca de cor exatamente onde o 7º selo abre.
    tracoDaVirada(OURO, limitar(fita * 0.11, 3, 5));
    ctx.save();
    ctx.translate(xVirada + barriga + limitar(L * 0.02, 6, 12), yMeio);
    ctx.rotate(Math.PI / 2);
    ctx.fillStyle = '#b07d10';
    ctx.font = `800 ${Math.round(A * 0.024)}px system-ui, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('a virada', 0, 0);
    ctx.restore();

    /** Uma medalha do rolo — selo ou trombeta. */
    function medalha(
      x: number,
      y: number,
      numero: number,
      cor: string,
      borda: string,
      acesa: boolean,
      raioBase: number,
    ): void {
      const raio = raioBase * (acesa ? 1.16 : 1);

      ctx.beginPath();
      ctx.arc(x, y, raio, 0, TAU);
      ctx.fillStyle = cor;
      if (acesa) {
        ctx.shadowColor = cor;
        ctx.shadowBlur = raio * 1.5;
      }
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.lineWidth = 1.4;
      ctx.strokeStyle = borda;
      ctx.stroke();

      // Reflexo: dá o volume de uma peça de metal.
      ctx.globalAlpha = 0.35;
      ctx.beginPath();
      ctx.ellipse(x - raio * 0.3, y - raio * 0.33, raio * 0.42, raio * 0.28, 0, 0, TAU);
      ctx.fillStyle = '#ffffff';
      ctx.fill();
      ctx.globalAlpha = 1;

      ctx.fillStyle = '#ffffff';
      ctx.font = `800 ${Math.round(raio * 0.95)}px system-ui, sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(String(numero), x, y);
    }

    for (let i = 0; i < 7; i++) {
      medalha(colunaX(i), yCima, i + 1, AZUL, AZUL_BORDA, seloAceso(i), raioSelo);
    }
    // As trombetas correm no sentido inverso: o rolo voltou.
    for (let i = 0; i < 7; i++) {
      medalha(colunaX(6 - i), yBaixo, i + 1, ROXO, ROXO_BORDA, trombetaAcesa(i), raioTrombeta);
    }

    // A 4ª visão se encaixa entre o 6º e o 7º selo: um pino sobre a fita.
    if (ramo === 'entre67') {
      const x = (colunaX(5) + colunaX(6)) / 2;
      const y = yCima - fita / 2 - raioSelo * 0.8;

      ctx.beginPath();
      ctx.arc(x, y, raioSelo * 0.5, 0, TAU);
      ctx.fillStyle = OURO;
      ctx.shadowColor = OURO;
      ctx.shadowBlur = raioSelo;
      ctx.fill();
      ctx.shadowBlur = 0;

      ctx.fillStyle = '#8a5f00';
      ctx.font = `800 ${Math.round(A * 0.024)}px system-ui, sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('4ª', x, y - raioSelo * 1.1);
    }

    // O miolo: o Reino, ao fim das trombetas.
    const pulso = reinoAceso ? 1 + Math.sin(t * 3) * 0.05 : 1;
    ctx.beginPath();
    ctx.arc(xReino, yBaixo, raioReino * pulso, 0, TAU);
    ctx.fillStyle = reinoAceso ? OURO : '#e7d29a';
    if (reinoAceso) {
      ctx.shadowColor = OURO;
      ctx.shadowBlur = raioReino * 0.9;
    }
    ctx.fill();
    ctx.shadowBlur = 0;
    ctx.lineWidth = 2.2;
    ctx.strokeStyle = reinoAceso ? '#fff3d0' : '#b07d10';
    ctx.stroke();

    ctx.fillStyle = reinoAceso ? '#4a3400' : '#7a6320';
    ctx.font = `800 ${Math.round(raioReino * 0.42)}px system-ui, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('O REINO', xReino, yBaixo - raioReino * 0.22);
    ctx.font = `${Math.round(raioReino * 0.34)}px system-ui, sans-serif`;
    ctx.fillText('11:15', xReino, yBaixo + raioReino * 0.28);

    // A faísca do desdobramento: percorre a virada (7º selo → trombetas) ou vai
    // da 7ª trombeta ao Reino — é o rolo virando e seguindo em frente.
    if (info.desdobra === true) {
      const k = (t * 0.55) % 1;
      const [x, y] =
        ramo === 'selo7' ? pontoDaVirada(k) : [colunaX(0) + (xReino - colunaX(0)) * k, yBaixo];

      ctx.beginPath();
      ctx.arc(x, y, raioSelo * 0.4, 0, TAU);
      ctx.fillStyle = OURO_CLARO;
      ctx.shadowColor = OURO;
      ctx.shadowBlur = raioSelo;
      ctx.globalAlpha = Math.sin(k * Math.PI);
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.globalAlpha = 1;
    }

    // ── Legenda ─────────────────────────────────────────────────────────────
    const yLegenda = A - A * 0.02;
    const tamanho = Math.round(A * 0.024);
    ctx.font = `600 ${tamanho}px system-ui, sans-serif`;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';

    let x = margem;
    for (const [cor, rotulo] of [
      [AZUL, 'os 7 selos'],
      [ROXO, 'as 7 trombetas'],
      [OURO, 'o Reino'],
    ] as const) {
      ctx.fillStyle = cor;
      ctx.beginPath();
      ctx.arc(x + tamanho * 0.42, yLegenda - tamanho * 0.34, tamanho * 0.42, 0, TAU);
      ctx.fill();
      ctx.fillStyle = FRACO;
      ctx.fillText(rotulo, x + tamanho * 1.15, yLegenda);
      x += tamanho * 1.15 + ctx.measureText(rotulo).width + tamanho * 0.9;
    }
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
    fundo: FUNDO,
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default revelacaoViz;
